{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated-run testing is undocumented; its absence cannot be inferred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score does not establish consistency across runs."
        }
      ],
      "instrument_review": "Test content, scoring, and intended scope are stated. The score describes one run on these puzzles; repeated-run consistency, puzzle selection, and conditions needed for fair system comparisons remain undocumented."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "A single evaluation provides no evidence of stability or instability across runs."
        }
      ],
      "instrument_review": "Exact-grid scoring and the narrow intended use are stated. The documented lack of repetition prevents assessment of score consistency. The 70% result supports description of this run, with puzzle selection and comparative conditions unspecified."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The developers tested score variation while holding the listed conditions constant."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability criterion of at most two percentage points."
        }
      ],
      "instrument_review": "Repeated evaluations support consistency under the listed conditions and the report's explicit stability definition. This evidence concerns the same system and puzzles; consistency across other systems, puzzle sets, or conditions remains unknown."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated-run testing under the listed constant conditions is explicitly reported."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability limit of two percentage points."
        }
      ],
      "instrument_review": "The repeated evaluations document a consistency problem under the report's criterion. The single 70% score inadequately represents the reported variation for comparisons. The cause of that variation and its implications for system rankings are unspecified."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation guidance does not establish that repeated-run testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions supply no evidence about score consistency."
        }
      ],
      "instrument_review": "Download and dependency instructions document setup, but provide no additional evaluation evidence. Exact-grid scoring supports interpretation of the reported run; stability, puzzle selection, and complete conditions for fair comparisons remain unspecified."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A solved more evaluated puzzles under the reported scoring and conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish a comparison of general intelligence across domains."
        }
      ],
      "instrument_review": "The reported comparison matches the narrow intended use. Exact-grid scoring and fixed instructions provide stated common features, but repeated-run consistency and other potentially relevant comparison conditions are unspecified. Conclusions should remain limited to the evaluated puzzles."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "The reported results show better performance by A on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broad intended use does not supply evidence of performance across domains."
        }
      ],
      "instrument_review": "The evidence supports the narrow puzzle comparison, but does not substantiate the stated use of selecting greater general intelligence across domains. Broader coverage and evidence connecting scores to that use are missing; consistency and full comparison conditions are also unspecified."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone provide no supplied evidence of improved workshop decisions with A versus B."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports greater correctness with A in the studied workshop; the reported difference interval is entirely positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "The trial supplies no measured safety comparison; improved correctness alone does not establish improved safety."
        }
      ],
      "instrument_review": "The preregistered randomized trial, new cases, blinded correctness checks, and reported uncertainty support the intended choice for decision correctness in this workshop. Initial test scores alone lacked this direct evidence. Other workshops, time, and safety remain outside the demonstrated outcomes; further trial and scoring details are unspecified."
    }
  ],
  "closing_note": "No material instruction ambiguity was identified. Missing evidence was labeled Not established; explicit conflicting evidence was labeled Contradicted."
}
